import{_ as t,o as d,c as r,a4 as e}from"./chunks/framework.BUqnS5H7.js";const g=JSON.parse('{"title":"RAG 架构与工程落地","description":"","frontmatter":{},"headers":[],"relativePath":"ai/03-RAG架构与工程落地.md","filePath":"ai/03-RAG架构与工程落地.md"}'),i={name:"ai/03-RAG架构与工程落地.md"};function s(n,a,l,c,o,h){return d(),r("div",null,[...a[0]||(a[0]=[e(`<h1 id="rag-架构与工程落地" tabindex="-1" data-src-line="1" data-src-file="ai/03-RAG架构与工程落地.md">RAG 架构与工程落地 <a class="header-anchor" href="#rag-架构与工程落地" aria-label="Permalink to &quot;RAG 架构与工程落地&quot;">​</a></h1><p data-src-line="3" data-src-file="ai/03-RAG架构与工程落地.md">上一篇解决了「怎么让 LLM 说话」。但 LLM 有个致命短板：<strong>它不知道你公司内部的知识。</strong> 你问它「我们公司的请假流程是什么」，它要么诚实地说「我不知道」，要么一本正经地编一段。</p><p data-src-line="5" data-src-file="ai/03-RAG架构与工程落地.md">这一篇回答一个核心问题：<strong>当你需要让 LLM 回答「只有你才知道的事实」时，怎么办。</strong> RAG（Retrieval-Augmented Generation，检索增强生成）是当前唯一经济可行的答案。读完你会发现，RAG 的骨架极其朴素，但它的<strong>工程细节</strong>才是决定「能用」还是「不能用」的关键——而这些细节，恰恰是大多数人学漏的。</p><hr><h2 id="_1-rag-是什么-给-llm-配一张「开卷小抄」" tabindex="-1" data-src-line="9" data-src-file="ai/03-RAG架构与工程落地.md">1. RAG 是什么：给 LLM 配一张「开卷小抄」 <a class="header-anchor" href="#_1-rag-是什么-给-llm-配一张「开卷小抄」" aria-label="Permalink to &quot;1. RAG 是什么：给 LLM 配一张「开卷小抄」&quot;">​</a></h2><h3 id="_1-1-闭卷-vs-开卷" tabindex="-1" data-src-line="11" data-src-file="ai/03-RAG架构与工程落地.md">1.1 闭卷 vs 开卷 <a class="header-anchor" href="#_1-1-闭卷-vs-开卷" aria-label="Permalink to &quot;1.1 闭卷 vs 开卷&quot;">​</a></h3><p data-src-line="13" data-src-file="ai/03-RAG架构与工程落地.md">闭卷考试 vs 开卷考试，就是原生 LLM 和 RAG 的关系。这个类比能帮你瞬间建立直觉：</p><table tabindex="0"><thead data-src-line="15" data-src-file="ai/03-RAG架构与工程落地.md"><tr data-src-line="15" data-src-file="ai/03-RAG架构与工程落地.md"><th>维度</th><th>闭卷（原生 LLM）</th><th>开卷（RAG）</th></tr></thead><tbody data-src-line="17" data-src-file="ai/03-RAG架构与工程落地.md"><tr data-src-line="17" data-src-file="ai/03-RAG架构与工程落地.md"><td>知识来源</td><td>脑子里背过的（预训练数据，<strong>会过时</strong>）</td><td>现场翻书（<strong>实时检索</strong>）</td></tr><tr data-src-line="18" data-src-file="ai/03-RAG架构与工程落地.md"><td>答错的后果</td><td>一本正经胡说八道（幻觉）</td><td>翻错页会答错，翻对了就有凭据</td></tr><tr data-src-line="19" data-src-file="ai/03-RAG架构与工程落地.md"><td>更新成本</td><td>要重新训练（天价）</td><td>往书架加本新书（增量灌库）</td></tr><tr data-src-line="20" data-src-file="ai/03-RAG架构与工程落地.md"><td>能否标出处</td><td>不能</td><td><strong>能</strong>——直接贴原文</td></tr></tbody></table><blockquote data-src-line="22" data-src-file="ai/03-RAG架构与工程落地.md"><p data-src-line="22" data-src-file="ai/03-RAG架构与工程落地.md">一句话心智模型：<strong>RAG = 给 LLM 配一个私有图书馆 + 一个精准的管理员。</strong> 管理员（检索）先把最相关的几页挑出来，连同问题一起递给 LLM；LLM 基于这些「原材料」续写答案，还能标注「这段来自哪本书」。</p></blockquote><p data-src-line="24" data-src-file="ai/03-RAG架构与工程落地.md">一旦建立这个画面，你就会发现一个贯穿全文的规律：<strong>RAG 的所有组件——向量库、Embedding、Chunk、Rerank、引用回链——都只是在优化「管理员怎么更快更准地把对的书挑出来」。</strong> 这句话记牢，后面每个组件你都不会迷路。</p><hr><h2 id="_2-为什么需要-rag-原生-llm-的三道死锁" tabindex="-1" data-src-line="28" data-src-file="ai/03-RAG架构与工程落地.md">2. 为什么需要 RAG：原生 LLM 的三道死锁 <a class="header-anchor" href="#_2-为什么需要-rag-原生-llm-的三道死锁" aria-label="Permalink to &quot;2. 为什么需要 RAG：原生 LLM 的三道死锁&quot;">​</a></h2><p data-src-line="30" data-src-file="ai/03-RAG架构与工程落地.md">直接拿 <code>gpt-4o</code> 回答「我们公司的请假流程」，你会同时撞上三堵墙：</p><table tabindex="0"><thead data-src-line="32" data-src-file="ai/03-RAG架构与工程落地.md"><tr data-src-line="32" data-src-file="ai/03-RAG架构与工程落地.md"><th>死锁</th><th>现象</th><th>为什么原生 LLM 解决不了</th></tr></thead><tbody data-src-line="34" data-src-file="ai/03-RAG架构与工程落地.md"><tr data-src-line="34" data-src-file="ai/03-RAG架构与工程落地.md"><td><strong>知识不在</strong></td><td>「我不知道贵司的 HR 政策」</td><td>训练数据里没有你的私有文档</td></tr><tr data-src-line="35" data-src-file="ai/03-RAG架构与工程落地.md"><td><strong>知识过时</strong></td><td>回答的是去年的通识</td><td>训练有截止日期，新政策它没见过</td></tr><tr data-src-line="36" data-src-file="ai/03-RAG架构与工程落地.md"><td><strong>没法溯源</strong></td><td>自信地编一段</td><td>生成式本质决定它无法标注出处</td></tr></tbody></table><h3 id="_2-1-三种方案对比-为什么是-rag" tabindex="-1" data-src-line="38" data-src-file="ai/03-RAG架构与工程落地.md">2.1 三种方案对比：为什么是 RAG <a class="header-anchor" href="#_2-1-三种方案对比-为什么是-rag" aria-label="Permalink to &quot;2.1 三种方案对比：为什么是 RAG&quot;">​</a></h3><p data-src-line="40" data-src-file="ai/03-RAG架构与工程落地.md">面对「让模型懂我的私有知识」，市面上有三条路，成本天差地别：</p><table tabindex="0"><thead data-src-line="42" data-src-file="ai/03-RAG架构与工程落地.md"><tr data-src-line="42" data-src-file="ai/03-RAG架构与工程落地.md"><th>方案</th><th>原理</th><th>成本</th><th>更新</th><th>能溯源</th><th>适用</th></tr></thead><tbody data-src-line="44" data-src-file="ai/03-RAG架构与工程落地.md"><tr data-src-line="44" data-src-file="ai/03-RAG架构与工程落地.md"><td>继续预训练</td><td>把私有数据重训进模型</td><td>百万级</td><td>每次重训</td><td>❌</td><td>几乎不做</td></tr><tr data-src-line="45" data-src-file="ai/03-RAG架构与工程落地.md"><td>微调 Fine-tuning</td><td>小样本调权重</td><td>万~十万级</td><td>增量微调</td><td>❌</td><td>改口吻/格式，非注入知识</td></tr><tr data-src-line="46" data-src-file="ai/03-RAG架构与工程落地.md"><td><strong>RAG</strong></td><td>问时现查，把原文塞进 Prompt</td><td>接入成本</td><td><strong>秒级增量</strong></td><td>✅</td><td><strong>95% 企业知识问答</strong></td></tr></tbody></table><p data-src-line="48" data-src-file="ai/03-RAG架构与工程落地.md"><strong>一个行业共识，也是新手最容易走岔的坑：先上 RAG，别上微调。</strong></p><p data-src-line="50" data-src-file="ai/03-RAG架构与工程落地.md">原因在于两者的<strong>使命根本不同</strong>：</p><ul data-src-line="52" data-src-file="ai/03-RAG架构与工程落地.md"><li data-src-line="52" data-src-file="ai/03-RAG架构与工程落地.md"><strong>微调</strong>解决的是「模型不会说话」——改它的口吻、格式、风格；</li><li data-src-line="53" data-src-file="ai/03-RAG架构与工程落地.md"><strong>RAG</strong>解决的是「模型不知道事实」——注入它没见过的知识。</li></ul><p data-src-line="55" data-src-file="ai/03-RAG架构与工程落地.md">绝大多数「公司 AI 助手」，要的是后者：<strong>你要的不是「更懂你的模型」，而是「能查你资料的模型」。</strong> 而「查资料」这件事，微调天生做不到——它把知识「背」进权重里，就没法实时更新、也没法溯源。所以一上来就微调，是典型的「用错了工具」。</p><h3 id="_2-2-rag-的本质-一个公式讲清所有花哨概念" tabindex="-1" data-src-line="57" data-src-file="ai/03-RAG架构与工程落地.md">2.2 RAG 的本质：一个公式讲清所有花哨概念 <a class="header-anchor" href="#_2-2-rag-的本质-一个公式讲清所有花哨概念" aria-label="Permalink to &quot;2.2 RAG 的本质：一个公式讲清所有花哨概念&quot;">​</a></h3><p data-src-line="59" data-src-file="ai/03-RAG架构与工程落地.md">RAG 的本质，用公式说清，胜过千言万语：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原生 LLM：answer = LLM(question)</span></span>
<span class="line"><span>RAG：     answer = LLM(question + retrieve(question, knowledgeBase))</span></span></code></pre></div><p data-src-line="66" data-src-file="ai/03-RAG架构与工程落地.md"><strong>整个 RAG 体系的所有优化，都只是在优化 <code>retrieve()</code> 这一个函数——怎么把最相关的几段原文挑出来。</strong> 切片、Embedding、混合检索、Rerank……所有让你眼花缭乱的名词，最后都收敛到这一句话上。记住它，你就有了「纲」，后面所有「目」都挂在它下面。</p><hr><h2 id="_3-两条流水线-五个组件" tabindex="-1" data-src-line="70" data-src-file="ai/03-RAG架构与工程落地.md">3. 两条流水线 + 五个组件 <a class="header-anchor" href="#_3-两条流水线-五个组件" aria-label="Permalink to &quot;3. 两条流水线 + 五个组件&quot;">​</a></h2><h3 id="_3-1-最重要的架构原则-两条流水线必须独立" tabindex="-1" data-src-line="72" data-src-file="ai/03-RAG架构与工程落地.md">3.1 最重要的架构原则：两条流水线必须独立 <a class="header-anchor" href="#_3-1-最重要的架构原则-两条流水线必须独立" aria-label="Permalink to &quot;3.1 最重要的架构原则：两条流水线必须独立&quot;">​</a></h3><p data-src-line="74" data-src-file="ai/03-RAG架构与工程落地.md">生产级 RAG <strong>一定是两条独立的流水线</strong>：</p><ul data-src-line="76" data-src-file="ai/03-RAG架构与工程落地.md"><li data-src-line="76" data-src-file="ai/03-RAG架构与工程落地.md"><strong>离线流水线（灌库）</strong>：数据源 → 同步 → 切片 → Embedding → 向量库</li><li data-src-line="77" data-src-file="ai/03-RAG架构与工程落地.md"><strong>在线流水线（问答）</strong>：提问 → 改写 → 召回 → Rerank → 组装 Prompt → 生成 → 引用回链</li></ul><p data-src-line="79" data-src-file="ai/03-RAG架构与工程落地.md"><strong>把两者混在一起做，是新手最常见的错误。</strong> 为什么必须分开？因为它们的<strong>节奏、触发方式、失败后果完全不同</strong>：灌库是「离线、批量、慢一点无所谓」；问答是「在线、实时、必须快」。混在一起，一个批量灌库任务就会拖慢在线问答的延迟。</p><h3 id="_3-2-五个组件-各管一件事" tabindex="-1" data-src-line="81" data-src-file="ai/03-RAG架构与工程落地.md">3.2 五个组件，各管一件事 <a class="header-anchor" href="#_3-2-五个组件-各管一件事" aria-label="Permalink to &quot;3.2 五个组件，各管一件事&quot;">​</a></h3><table tabindex="0"><thead data-src-line="83" data-src-file="ai/03-RAG架构与工程落地.md"><tr data-src-line="83" data-src-file="ai/03-RAG架构与工程落地.md"><th>组件</th><th>职责</th><th>一句话</th></tr></thead><tbody data-src-line="85" data-src-file="ai/03-RAG架构与工程落地.md"><tr data-src-line="85" data-src-file="ai/03-RAG架构与工程落地.md"><td><strong>Chunker</strong></td><td>把长文档切成小片段</td><td>切片质量决定召回上限</td></tr><tr data-src-line="86" data-src-file="ai/03-RAG架构与工程落地.md"><td><strong>Embedding</strong></td><td>把文本变成向量</td><td>语义相近 → 向量相近</td></tr><tr data-src-line="87" data-src-file="ai/03-RAG架构与工程落地.md"><td><strong>向量库</strong></td><td>存向量 + 快速检索</td><td>找「最像」的片段</td></tr><tr data-src-line="88" data-src-file="ai/03-RAG架构与工程落地.md"><td><strong>Rerank</strong></td><td>对召回结果二次精排</td><td>性价比最高的一步优化</td></tr><tr data-src-line="89" data-src-file="ai/03-RAG架构与工程落地.md"><td><strong>Citation</strong></td><td>答案对回原文出处</td><td>建立信任的杠杆</td></tr></tbody></table><p data-src-line="91" data-src-file="ai/03-RAG架构与工程落地.md">这五个组件的责任边界非常清晰，后面几节就是逐个讲透它们各自的「坑」。</p><hr><h2 id="_4-离线流水线-最容易被低估的脏活" tabindex="-1" data-src-line="95" data-src-file="ai/03-RAG架构与工程落地.md">4. 离线流水线：最容易被低估的脏活 <a class="header-anchor" href="#_4-离线流水线-最容易被低估的脏活" aria-label="Permalink to &quot;4. 离线流水线：最容易被低估的脏活&quot;">​</a></h2><p data-src-line="97" data-src-file="ai/03-RAG架构与工程落地.md">离线灌库看似「不就是切片+向量化吗」，实则是<strong>决定 RAG 效果上限的最脏、最被低估的活</strong>。</p><h3 id="_4-1-切片-chunking-是效果的天花板" tabindex="-1" data-src-line="99" data-src-file="ai/03-RAG架构与工程落地.md">4.1 切片（Chunking）是效果的天花板 <a class="header-anchor" href="#_4-1-切片-chunking-是效果的天花板" aria-label="Permalink to &quot;4.1 切片（Chunking）是效果的天花板&quot;">​</a></h3><p data-src-line="101" data-src-file="ai/03-RAG架构与工程落地.md">切片切得好不好，直接决定召回质量的上限——<strong>切片切烂了，后面 Rerank 再强也救不回来</strong>（因为它能选的候选本身就错了）。三条口诀：</p><p data-src-line="103" data-src-file="ai/03-RAG架构与工程落地.md"><strong>口诀一：带重叠。</strong> 相邻 chunk 重叠 10%~20%，防止一段语义被硬生生切在 chunk 边界上。比如一句话「……审批流程如下」被切到 chunk A 结尾，而真正的流程在 chunk B 开头，不重叠就召回不全。</p><p data-src-line="105" data-src-file="ai/03-RAG架构与工程落地.md"><strong>口诀二：带 metadata。</strong> 每个 chunk 强制带 <code>{doc_id, title, section, url, tenant_id}</code>。这是后续<strong>过滤、引用回链、权限隔离</strong>的命脉——没有 metadata，你后面什么都做不了。</p><p data-src-line="107" data-src-file="ai/03-RAG架构与工程落地.md"><strong>口诀三：注入标题路径。</strong> 给每个 chunk 文本前加「《文档标题》→ 章节标题」。因为 chunk 会被<strong>独立</strong>召回、独立理解，如果不带标题，「它的审批流程」里的「它」就丢了，模型根本不知道这段在讲谁。</p><h3 id="_4-2-换-embedding-模型-整库重灌" tabindex="-1" data-src-line="109" data-src-file="ai/03-RAG架构与工程落地.md">4.2 换 Embedding 模型 = 整库重灌 <a class="header-anchor" href="#_4-2-换-embedding-模型-整库重灌" aria-label="Permalink to &quot;4.2 换 Embedding 模型 = 整库重灌&quot;">​</a></h3><p data-src-line="111" data-src-file="ai/03-RAG架构与工程落地.md">这是生产级 RAG <strong>最沉重、最容易被忽视</strong>的运维成本：</p><p data-src-line="113" data-src-file="ai/03-RAG架构与工程落地.md"><strong>查询向量和文档向量必须来自同一个模型。</strong> 因为向量空间是「模型专属」的——A 模型把「猫」映射到坐标 (0.1, 0.8)，B 模型可能映射到 (0.9, 0.2)。你拿 A 模型的查询向量，去 B 模型的文档向量库里搜，搜出来的全是乱码。</p><p data-src-line="115" data-src-file="ai/03-RAG架构与工程落地.md">所以<strong>一旦上线后决定换 Embedding 模型，整个向量库必须全量重灌</strong>。这不是「改个配置」的小事，而是一次全量数据迁移。</p><p data-src-line="117" data-src-file="ai/03-RAG架构与工程落地.md"><strong>结论</strong>：选型阶段务必<strong>跑一批真实业务样本做召回率对比</strong>，别凭榜单拍板。中文场景开源首选 <code>bge-m3</code> 或 <code>bce-embedding</code>——先想清楚、测清楚，再定模型，因为定了之后就很难换。</p><h3 id="_4-3-向量库选型-先别急着上专用库" tabindex="-1" data-src-line="119" data-src-file="ai/03-RAG架构与工程落地.md">4.3 向量库选型：先别急着上专用库 <a class="header-anchor" href="#_4-3-向量库选型-先别急着上专用库" aria-label="Permalink to &quot;4.3 向量库选型：先别急着上专用库&quot;">​</a></h3><p data-src-line="121" data-src-file="ai/03-RAG架构与工程落地.md">一条经验法则，能帮你省掉一大笔不必要的运维成本：</p><p data-src-line="123" data-src-file="ai/03-RAG架构与工程落地.md"><strong>百万级 chunk 以内，用你已有的 PgVector 或 ES 就够，不新增组件。</strong> 只有数据上到千万级、或 QPS 很高，才值得引入 Milvus 这类专用向量库。</p><p data-src-line="125" data-src-file="ai/03-RAG架构与工程落地.md">原因很实在：<strong>新组件 = 新的监控、备份、运维人力</strong>。为了一百万条向量，专门养一个 Milvus 集群，这笔账不划算。<strong>先复用已有基础设施，等规模真的逼上来了，再迁移。</strong></p><hr><h2 id="_5-在线流水线-怎么查得准" tabindex="-1" data-src-line="129" data-src-file="ai/03-RAG架构与工程落地.md">5. 在线流水线：怎么查得准 <a class="header-anchor" href="#_5-在线流水线-怎么查得准" aria-label="Permalink to &quot;5. 在线流水线：怎么查得准&quot;">​</a></h2><p data-src-line="131" data-src-file="ai/03-RAG架构与工程落地.md">在线问答这条流水线，是决定「用户体感好还是差」的关键。四步，每一步都有它的诀窍。</p><h3 id="_5-1-query-改写-提问质量的第一道闸门" tabindex="-1" data-src-line="133" data-src-file="ai/03-RAG架构与工程落地.md">5.1 Query 改写：提问质量的第一道闸门 <a class="header-anchor" href="#_5-1-query-改写-提问质量的第一道闸门" aria-label="Permalink to &quot;5.1 Query 改写：提问质量的第一道闸门&quot;">​</a></h3><p data-src-line="135" data-src-file="ai/03-RAG架构与工程落地.md">用户原始提问通常很烂——短、有代词、有口语。直接拿去检索，效果很差：</p><ul data-src-line="137" data-src-file="ai/03-RAG架构与工程落地.md"><li data-src-line="137" data-src-file="ai/03-RAG架构与工程落地.md">「那生病呢？」——「生病」指什么？前面聊的请假？病假？</li><li data-src-line="138" data-src-file="ai/03-RAG架构与工程落地.md">「这个怎么弄？」——「这个」指代不明。</li></ul><p data-src-line="140" data-src-file="ai/03-RAG架构与工程落地.md">几个套路：<strong>问题澄清</strong>（补全主语）、<strong>同义扩写</strong>（提高召回）、<strong>多轮消解</strong>（把「那生病呢」还原成「那生病请假怎么请」）。</p><p data-src-line="142" data-src-file="ai/03-RAG架构与工程落地.md">落地技巧：改写本身就是<strong>一次小 LLM 调用</strong>（用便宜模型即可），<strong>把改写和意图识别合并在一个 Prompt 里一次拿到</strong>，别拆成多次调用——省一次调用，就省一份延迟和成本。</p><h3 id="_5-2-混合检索-别只靠语义向量" tabindex="-1" data-src-line="144" data-src-file="ai/03-RAG架构与工程落地.md">5.2 混合检索：别只靠语义向量 <a class="header-anchor" href="#_5-2-混合检索-别只靠语义向量" aria-label="Permalink to &quot;5.2 混合检索：别只靠语义向量&quot;">​</a></h3><p data-src-line="146" data-src-file="ai/03-RAG架构与工程落地.md">这是新手最常犯的「技术选型错误」——以为「向量检索就够了」。其实有两类查询，向量的表现截然不同：</p><ul data-src-line="148" data-src-file="ai/03-RAG架构与工程落地.md"><li data-src-line="148" data-src-file="ai/03-RAG架构与工程落地.md"><strong>语义相似</strong>（「怎么请假」「休假流程」）→ 稠密向量擅长；</li><li data-src-line="149" data-src-file="ai/03-RAG架构与工程落地.md"><strong>精确术语</strong>（型号编码 <code>iPhone 15 Pro Max</code>、订单号 <code>ORDER-2024-001</code>）→ 关键词（BM25）反而更准，因为「iPhone 15 Pro Max」这种精确字符串，向量相似度反而不如 BM25 的字符匹配。</li></ul><p data-src-line="151" data-src-file="ai/03-RAG架构与工程落地.md"><strong>生产推荐做法（混合检索）</strong>：向量召回 TopK=20 + BM25 召回 TopK=20 → 融合去重（用 RRF 算法）→ 再进 Rerank。两者互补，召回率显著高于任一单用。</p><h3 id="_5-3-rerank-性价比最高的一步优化" tabindex="-1" data-src-line="153" data-src-file="ai/03-RAG架构与工程落地.md">5.3 Rerank：性价比最高的一步优化 <a class="header-anchor" href="#_5-3-rerank-性价比最高的一步优化" aria-label="Permalink to &quot;5.3 Rerank：性价比最高的一步优化&quot;">​</a></h3><p data-src-line="155" data-src-file="ai/03-RAG架构与工程落地.md">Rerank 是「精排」，粗排（向量召回）从千万文档里捞 20 条，精排（Rerank）从 20 条里选出最相关的 Top 5。</p><p data-src-line="157" data-src-file="ai/03-RAG架构与工程落地.md">Reranker 是「句对打分」模型——它直接对「问题 + 候选片段」这一对做精细的相关性打分，精度比「向量余弦相似度」这种粗排高得多。</p><p data-src-line="159" data-src-file="ai/03-RAG架构与工程落地.md"><strong>加一个 Reranker，通常能把命中率从 ~70% 拉到 ~90%，延迟只增加几十毫秒。</strong> 这是 RAG 所有优化里<strong>性价比最高</strong>的一步——投入最小，收益最大。如果只做一件优化，就做这个。</p><h3 id="_5-4-引用回链-让答案「有据可依」" tabindex="-1" data-src-line="161" data-src-file="ai/03-RAG架构与工程落地.md">5.4 引用回链：让答案「有据可依」 <a class="header-anchor" href="#_5-4-引用回链-让答案「有据可依」" aria-label="Permalink to &quot;5.4 引用回链：让答案「有据可依」&quot;">​</a></h3><p data-src-line="163" data-src-file="ai/03-RAG架构与工程落地.md">Prompt 里要求模型用 <code>[doc_id:chunk_id]</code> 标注事实出处，后处理程序再把这些 ID 换成可点击的链接/脚注。</p><p data-src-line="165" data-src-file="ai/03-RAG架构与工程落地.md"><strong>企业场景里，没有引用的 AI 回答 = 「一个不敢签字的专家意见」。</strong> 引用让用户一眼判断能不能信、原文在哪、要不要进一步核实。<strong>这是 RAG 能在法务、医疗、HR 这类严肃场景落地、而原生 LLM 不能的关键差异</strong>——因为它能溯源，所以能被审计、被信任。</p><hr><h2 id="_6-怎么守住可靠-安全-本篇命门" tabindex="-1" data-src-line="169" data-src-file="ai/03-RAG架构与工程落地.md">6. 怎么守住可靠 + 安全（本篇命门） <a class="header-anchor" href="#_6-怎么守住可靠-安全-本篇命门" aria-label="Permalink to &quot;6. 怎么守住可靠 + 安全（本篇命门）&quot;">​</a></h2><p data-src-line="171" data-src-file="ai/03-RAG架构与工程落地.md">RAG 的命门是「可靠 + 安全」双线，缺一不可。</p><h3 id="_6-1-可靠-没有评测集-rag-就是盲调" tabindex="-1" data-src-line="173" data-src-file="ai/03-RAG架构与工程落地.md">6.1 可靠：没有评测集，RAG 就是盲调 <a class="header-anchor" href="#_6-1-可靠-没有评测集-rag-就是盲调" aria-label="Permalink to &quot;6.1 可靠：没有评测集，RAG 就是盲调&quot;">​</a></h3><p data-src-line="175" data-src-file="ai/03-RAG架构与工程落地.md">你改了切片参数、换了模型、加了 Rerank——<strong>到底变好还是变差？只能靠数据说。</strong> 否则就是「盲调」，改了半天，可能越改越差还不自知。</p><p data-src-line="177" data-src-file="ai/03-RAG架构与工程落地.md">至少要拉一个指标：<strong><code>Recall@K</code></strong>（该被召回的片段，有没有出现在 Top K 里）。</p><p data-src-line="179" data-src-file="ai/03-RAG架构与工程落地.md">工程化做法：建一个 <code>(问题, 标准答案, 必含片段ID)</code> 的评测集，任何改动都先跑评测基线再合入。<strong>这和 09 篇的「评测集」是同一套方法论</strong>——RAG 的可靠，同样建立在可量化的评测之上，而不是「感觉不错」。</p><h3 id="_6-2-安全-权限隔离必须做在每一层" tabindex="-1" data-src-line="181" data-src-file="ai/03-RAG架构与工程落地.md">6.2 安全：权限隔离必须做在每一层 <a class="header-anchor" href="#_6-2-安全-权限隔离必须做在每一层" aria-label="Permalink to &quot;6.2 安全：权限隔离必须做在每一层&quot;">​</a></h3><p data-src-line="183" data-src-file="ai/03-RAG架构与工程落地.md">企业知识库一定有权限边界——A 部门的文档，B 部门不该看到。这是<strong>安全级</strong>问题，三个硬性要求，一个都不能省：</p><ol data-src-line="185" data-src-file="ai/03-RAG架构与工程落地.md"><li data-src-line="185" data-src-file="ai/03-RAG架构与工程落地.md"><strong>灌库时</strong>：每个 chunk 的 metadata 必须带 <code>{tenant_id, visibility}</code>；</li><li data-src-line="186" data-src-file="ai/03-RAG架构与工程落地.md"><strong>检索时</strong>：强制 <code>filter={tenant_id: X}</code>，<strong>绝不要在召回后靠应用层兜底过滤</strong>（那样会有越权检索漏洞——不该召回的片段已经被召回了，再过滤已经太晚）；</li><li data-src-line="187" data-src-file="ai/03-RAG架构与工程落地.md"><strong>生成后</strong>：再做一次「引用 ID 是否属于该用户」的二次校验，兜底防线。</li></ol><p data-src-line="189" data-src-file="ai/03-RAG架构与工程落地.md"><strong>核心原则：权限过滤必须「下沉」到检索这一层（向量库的 filter），而不是「上浮」到应用层事后补救。</strong> 这一层没守住，后面全都白搭。</p><hr><h2 id="_7-最常踩的几个坑" tabindex="-1" data-src-line="193" data-src-file="ai/03-RAG架构与工程落地.md">7. 最常踩的几个坑 <a class="header-anchor" href="#_7-最常踩的几个坑" aria-label="Permalink to &quot;7. 最常踩的几个坑&quot;">​</a></h2><table tabindex="0"><thead data-src-line="195" data-src-file="ai/03-RAG架构与工程落地.md"><tr data-src-line="195" data-src-file="ai/03-RAG架构与工程落地.md"><th>现象</th><th>根因</th><th>正确姿势</th></tr></thead><tbody data-src-line="197" data-src-file="ai/03-RAG架构与工程落地.md"><tr data-src-line="197" data-src-file="ai/03-RAG架构与工程落地.md"><td>Top 5 总没有真正相关的</td><td>Chunk 切太大 / 模型不适配</td><td>减小 chunk；换中文 embedding</td></tr><tr data-src-line="198" data-src-file="ai/03-RAG架构与工程落地.md"><td>答案里出现 <code>[doc=XYZ]</code> 但库里没有</td><td>LLM 编造引用 ID</td><td>后处理校验 ID 是否存在，不存在整句丢弃</td></tr><tr data-src-line="199" data-src-file="ai/03-RAG架构与工程落地.md"><td>加了 RAG 反而更糟</td><td>召回根本没命中</td><td><strong>先单独测检索层 Recall@K，别盯着最终答案</strong></td></tr><tr data-src-line="200" data-src-file="ai/03-RAG架构与工程落地.md"><td>A 租户查到 B 租户的文档</td><td>检索没做 metadata 过滤</td><td>检索强制 filter，生成后再二次校验</td></tr><tr data-src-line="201" data-src-file="ai/03-RAG架构与工程落地.md"><td>只靠向量检索，精确术语搜不到</td><td>忽略了关键词检索</td><td>混合检索：向量 + BM25，再 RRF 融合</td></tr><tr data-src-line="202" data-src-file="ai/03-RAG架构与工程落地.md"><td>换了 embedding 模型，全库乱码</td><td>查询/文档向量不同源</td><td>换模型必须整库重灌</td></tr></tbody></table><hr><h2 id="_8-记住这一句" tabindex="-1" data-src-line="206" data-src-file="ai/03-RAG架构与工程落地.md">8. 记住这一句 <a class="header-anchor" href="#_8-记住这一句" aria-label="Permalink to &quot;8. 记住这一句&quot;">​</a></h2><blockquote data-src-line="208" data-src-file="ai/03-RAG架构与工程落地.md"><p data-src-line="208" data-src-file="ai/03-RAG架构与工程落地.md"><strong>RAG 的本质 = 把 <code>P(答案|问题)</code> 改造成 <code>P(答案|问题, 检索到的上下文)</code>；其余所有组件都只是优化 <code>retrieve()</code> 这一个函数。</strong></p><p data-src-line="210" data-src-file="ai/03-RAG架构与工程落地.md">三条硬规则：<strong>两条流水线独立</strong>、<strong>Embedding 一换整库重灌</strong>、<strong>没有评测集的 RAG 等于盲调。</strong></p></blockquote><p data-src-line="212" data-src-file="ai/03-RAG架构与工程落地.md">下一篇预告：RAG 解决了「懂资料」，可 LLM 还是只会「说」，不会「做」——它不能查数据库、不能调 API、不能操作系统。这就到了 <strong>04 · Function Calling 与 Agent 范式</strong>。</p>`,88)])])}const m=t(i,[["render",s]]);export{g as __pageData,m as default};
